import{_ as i,o as s,c as a,a2 as t}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Raspberry Pi Imager Provisioning","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/operations/raspberry-pi-imager-provisioning.md"},"headers":[],"relativePath":"sovereign-os/guides/raspberry-pi-imager-provisioning.md","filePath":"sovereign-os/guides/raspberry-pi-imager-provisioning.md"}'),r={name:"sovereign-os/guides/raspberry-pi-imager-provisioning.md"};function n(o,e,p,l,h,d){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="raspberry-pi-imager-provisioning" tabindex="-1">Raspberry Pi Imager Provisioning <a class="header-anchor" href="#raspberry-pi-imager-provisioning" aria-label="Permalink to &quot;Raspberry Pi Imager Provisioning&quot;">​</a></h1><p><strong>Status:</strong> Implemented; physical Raspberry Pi 5 verification pending</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Sovereign OS accepts Raspberry Pi Imager&#39;s <code>rpi-preseed</code> customization file on first boot. This lets a user put Wi-Fi and an SSH public key into a freshly flashed device without modifying the Linux filesystems by hand or connecting a keyboard and display.</p><p>Preview images covered by ADR-0003 include a temporary bootstrap account for the ordinary custom-image workflow. Imager provisioning can replace that onboarding path with per-device settings written to the boot partition. Sovereign consumes that file before networking and SSH start, then deletes it from the boot partition.</p><h2 id="flash-with-customization" tabindex="-1">Flash with Customization <a class="header-anchor" href="#flash-with-customization" aria-label="Permalink to &quot;Flash with Customization&quot;">​</a></h2><p>This workflow requires Raspberry Pi Imager 2.0.11 or later. Earlier Imager 2.x releases reject <code>rpi-preseed</code> manifests and silently omit the Sovereign OS entry from the operating-system list. While 2.0.11 is available only as a release candidate, use the official 2.0.11-rc1 build for POC qualification.</p><p>Download the complete release bundle and verify it from inside its directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS</span></span></code></pre></div><p>Create the small local Imager catalog beside the downloaded image:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-imager-manifest.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  sovereign-os-0.1.0-preview.1-rpi5-arm64.img.zst</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.1.0-preview.1</span></span></code></pre></div><p>If Imager 2.0.11-rc1 reports the compressed-file SHA-256 as the &quot;Actual&quot; uncompressed hash, decompress the local image and generate the manifest from the raw file instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zstd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --decompress</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign-os-0.1.0-preview.1-rpi5-arm64.img.zst</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign-os-0.1.0-preview.1-rpi5-arm64.img</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create-imager-manifest.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  sovereign-os-0.1.0-preview.1-rpi5-arm64.img</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.1.0-preview.1</span></span></code></pre></div><p>This preserves full SHA-256 verification but requires approximately 3.2 GB of additional local disk space for the current image.</p><p>Open <code>sovereign-os.rpi-imager-manifest</code> with Raspberry Pi Imager. Select the Sovereign OS entry, select the target storage, and configure:</p><ul><li>the Wi-Fi SSID, password, and country when Ethernet will not be used;</li><li>SSH with a public key, which is the recommended diagnostic access method;</li><li>the operator username and password if desired; and</li><li>timezone.</li></ul><p>Keep the hostname as <code>sovereign</code>. The appliance owns that hostname so its local address remains <code>sovereign.local</code>. Write the image, insert the storage into the Pi, and power it on.</p><p>On a compatible Raspberry Pi Imager, selecting the <code>.img.zst</code> through <strong>Use custom</strong> does not advertise an initialization format and therefore does not present OS customization. Open the supplied <code>.rpi-imager-manifest</code> instead.</p><h2 id="first-boot-behavior" tabindex="-1">First-Boot Behavior <a class="header-anchor" href="#first-boot-behavior" aria-label="Permalink to &quot;First-Boot Behavior&quot;">​</a></h2><p><code>sovereign-imager-provision.service</code> runs before IWD, SSH, and the Sovereign appliance services. It supports the following <code>rpi-preseed</code> settings:</p><ul><li>operator username, encrypted password, supplementary groups, and optional passwordless sudo;</li><li>SSH authorized keys and optional password authentication;</li><li>open, WPA-PSK, and SAE Wi-Fi, including hidden SSIDs and a regulatory country;</li><li>timezone.</li></ul><p>Wi-Fi is translated to a root-only IWD network profile. SSH remains configured with root login disabled. Key authentication is recommended. Preview images temporarily ship the bootstrap access described in <a href="./../adrs/0003-preview-bootstrap-access.html">ADR-0003</a>; it must be replaced on first login and is not the production credential model.</p><p>The hostname is intentionally fixed to <code>sovereign</code>; a different Imager value is ignored. Raspberry Pi Connect and custom network-interface definitions are not part of this POC.</p><p>After success, non-secret status is recorded at:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/sovereign/imager-provisioning.json</span></span>
<span class="line"><span>/data/sovereign/imager-provisioned</span></span></code></pre></div><p>The source credential file at <code>/boot/firmware/rpi-preseed.toml</code> is removed as soon as it has been parsed, including when validation fails. A failed initial configuration must be corrected by flashing again; Sovereign does not preserve the credential-bearing input for retry.</p><h2 id="connect" tabindex="-1">Connect <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;Connect&quot;">​</a></h2><p>Allow several minutes for initial appliance setup, then try:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">operato</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">@sovereign.local</span></span></code></pre></div><p>If mDNS is unavailable, find the address in the router&#39;s DHCP client list and use <code>ssh &lt;operator&gt;@&lt;address&gt;</code>. The web entry point is <code>http://sovereign.local/</code>, with the direct IP as a fallback.</p><h2 id="compatibility-boundary" tabindex="-1">Compatibility Boundary <a class="header-anchor" href="#compatibility-boundary" aria-label="Permalink to &quot;Compatibility Boundary&quot;">​</a></h2><p>This is a Sovereign-owned compatible consumer of the documented Raspberry Pi Imager <code>rpi-preseed</code> format, not the Raspberry Pi <code>rpi-preseed</code> Debian package. The supported subset is tested in this repository and must be qualified with the current Imager release and a physical Raspberry Pi 5 before publication.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://www.raspberrypi.com/documentation/computers/getting-started.html" target="_blank" rel="noreferrer">Raspberry Pi Imager and OS customization</a></li><li><a href="https://github.com/raspberrypi/rpi-imager/blob/main/doc/os_customisation_formats.md" target="_blank" rel="noreferrer">Raspberry Pi Imager OS customization formats</a></li><li><a href="https://kernel.googlesource.com/pub/scm/network/wireless/iwd/+/refs/tags/3.4/src/iwd.network.rst" target="_blank" rel="noreferrer">IWD network configuration</a></li></ul>`,34)])])}const m=i(r,[["render",n]]);export{g as __pageData,m as default};
